/* https://soclinic.uk/wp-content/plugins/bookly-responsive-appointment-booking-too */
:root {
    --bookly-css-version: "28.5";
}

.bookly-list-none {
    list-style: none;
}

.bookly-left {
    float: left !important;
}

.bookly-right {
    float: right !important;
}

.bookly-clear {
    clear: both !important;
}

.bookly-rtext {
    text-align: right !important;
}

.bookly-text-center {
    text-align: center;
}

.bookly-bold {
    font-weight: bold !important;
}

.bookly-list {
    margin-left: 10px !important;
}

.bookly-clear-bottom {
    margin-bottom: 0 !important;
}

.bookly-none {
    display: none !important;
}

.bookly-nowrap {
    white-space: nowrap;
}

.bookly-inline-block {
    display: inline-block !important;
}

.bookly-btn {
    text-decoration: none;
}

.bookly-btn[disabled], .bookly-btn-submit[disabled] {
    opacity: 0.5;
}

.bookly-font-mono {
    font-family: monospace !important;
}

/* Layout */
.bookly-box {
    margin: 0 0 20px;
    overflow: hidden;
}

.bookly-table {
    display: table;
    table-layout: fixed;
    width: 100%;
}

.bookly-table > * {
    display: table-cell;
    vertical-align: top;
    width: auto;
}

.bookly-table::before,
.bookly-table::after {
    content: unset !important;
}

/* Form Elements */
.bookly-form {
    margin: 0 auto;
}

.bookly-form * {
    box-sizing: border-box;
    font-family: inherit;
    font-size: 14px;
    line-height: inherit;
}

.bookly-form input[type="text"],
.bookly-form input[type="tel"],
.bookly-form input[type="number"],
.bookly-form input[type="password"],
.bookly-form select,
.bookly-form textarea {
    font-size: 14px !important;
    line-height: normal !important;
    border: 1px solid silver !important;
    border-radius: 4px !important;
    width: 100% !important;
}

.bookly-form input[type="text"],
.bookly-form input[type="tel"],
.bookly-form input[type="number"],
.bookly-form input[type="password"],
.bookly-form select {
    height: auto !important;
}

.bookly-form input[type="text"],
.bookly-form input[type="tel"],
.bookly-form input[type="checkbox"],
.bookly-form input[type="radio"],
.bookly-form input[type="number"],
.bookly-form input[type="password"],
.bookly-form select,
.bookly-form textarea {
    display: inline-block;
    margin: 0 !important;
    outline: none !important;
}

.bookly-form input[type="text"],
.bookly-form input[type="tel"],
.bookly-form input[type="number"],
.bookly-form input[type="password"],
.bookly-form textarea {
    padding-top: 6px !important;
    padding-bottom: 5px !important;
    padding-right: 7px !important;
}

.bookly-form input[type="text"]:not(.iti__tel-input),
.bookly-form input[type="tel"]:not(.iti__tel-input),
.bookly-form input[type="number"],
.bookly-form input[type="password"],
.bookly-form textarea {
    padding-left: 7px !important;
}

.bookly-form select {
