/* https://soclinic.uk/wp-content/plugins/bookly-addon-pro/frontend/modules/custome */
.bookly-customer-appointment-list {
    overflow: auto;
}

.bookly-customer-appointment-list h2 {
    margin: 20px 0;
    font-size: 25px;
    padding-bottom: 15px;
    border-bottom: 1px solid silver;
}

.bookly-customer-appointment-list .bookly-appointments-table {
    border: 1px solid silver;
    border-collapse: collapse;
    table-layout: auto;
}

.bookly-customer-appointment-list .bookly-appointments-table th {
    background: #ddd;
    font-size: 14px;
    padding: 5px;
    border: 0;
    white-space: nowrap;
    text-align: center;
}

.bookly-customer-appointment-list table.bookly-appointments-table td {
    font-size: 14px;
    padding: 5px !important;
    background: #eee;
    text-align: left;
    vertical-align: top !important;
    border: 1px solid silver;
}

.bookly-customer-appointment-list table.bookly-appointments-table td.bookly-text-right {
    text-align: right;
}

.bookly-btn-default {
    padding: 9px 18px!important;
    border: 0!important;
    min-width: 118px;
    display: block;
    text-align: center;
    border-radius: 4px!important;
    background: #f4662f;
    cursor: pointer!important;
    height: auto!important;
    outline: none!important;
    text-decoration: none;
}

.bookly-btn-default, .bookly-btn-default > span {
    color: #fff!important;
    font-size: 18px!important;
    line-height: 17px!important;
    font-weight: bold!important;
    text-transform: uppercase!important;
}

.bookly-customer-appointment-list ul.bookly-extras {
    list-style: disc outside !important;
    margin-bottom: 0 !important;
}

