/* inline: widget: Woo Product Grid #uc_woocommerce_product_gr */
/* widget: Woo Product Grid */



#uc_woocommerce_product_grid_elementor_41904dc * {
	-webkit-box-sizing: border-box;
	-moz-box-sizing: border-box;
	box-sizing: border-box;    
}


#uc_woocommerce_product_grid_elementor_41904dc .ue_woocommerce_product_label-custom-field{
	z-index: 100;
}

#uc_woocommerce_product_grid_elementor_41904dc .ue_category_wrapper{
  display: flex;
  flex-wrap: wrap;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_post_grid_style_one_item{
	transition: all.3s;
}

#uc_woocommerce_product_grid_elementor_41904dc span.add-to-cart__loader{
  	position: absolute;
  	right: 0;
  	top: 50%;
  	transform: translate(0, -50%);
  	line-height: 1em;
}
#uc_woocommerce_product_grid_elementor_41904dc .add_to_cart_button.loading span.add-to-cart__loader{
	display: inline-block !important;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc-grid-count-buttons{
	display: flex;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc-grid-count-buttons button{
	display: flex;
    align-items:center;
    justify-content:center;
    flex-grow:0;
    flex-shrink:0;
    line-height:1em;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc-grid-count-buttons button:disabled{
	opacity:0.5;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_more_btn-custom-field{
  text-align:center;
  text-decoration:none;
  transition:0.3s;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc-grid-count-buttons button svg{
	height:1em;
    width:1em;
}

#uc_woocommerce_product_grid_elementor_41904dc input.uc-grid-count-buttons__number{
  text-align:center;
  flex-grow:1;
}

#uc_woocommerce_product_grid_elementor_41904dc {
  margin:0 auto;
  position:relative;  
}

.uc_post_grid_style_one .uc_post_grid_style_one_item {
	color: #111;
	font-size: 16px;
	overflow: hidden;
  	position: relative;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_post_grid_style_one_image {
	width: 100%;
	overflow: hidden;
	display: block;
  	position: relative;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_post_image {
    position:relative;
	display: block;
	transition: all 0.25s ease-in-out;
    overflow:hidden;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_post_image--second{
  	width: 100%;
    height: 100%;
    object-fit: cover;
	position: absolute;
  	top: 0;
  	right: 0;
  	  		  			transform: translate(100%, 0);
  		    
  	 
  	transition: all .3s;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_post_grid_style_one_image:hover .uc_post_image--second{  
  			transform: translate(0, 0);
  	}

#uc_woocommerce_product_grid_elementor_41904dc  .uc_post_image img
{
  width:100%;
  display: block;
  transition:0.3s;
}


.uc_post_grid_style_one .uc_title {
    font-size: 21px;   
}

.uc_post_grid_style_one .uc_title a {
	text-decoration: none;
   transition: all .3s ease;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_post_grid_style_one_button > button,
#uc_woocommerce_product_grid_elementor_41904dc .uc_more_btn-custom-field{
	width: 100%;
}

#uc_woocommerce_product_grid_elementor_41904dc .uc_post_grid_style_one_button > a,
#uc_woocommerce_product_grid_elementor_41904dc .uc_post_grid_style_one_button > button,
#uc_woocommerce_product_grid_elementor_41904dc .uc-button-addcart,
#uc_woocommerce_product_grid_elementor_41904dc .added_to_cart,
#uc_woocommerce_product_grid_elementor_41904dc .uc_more_btn-custom-field{
	display: block;
	text-align: center;
    text-decoration: none;
    text-transform: none;
	transition: all 0.25s ease-in-out;
    vertical-align: middle;
}

  #uc_woocommerce_product_grid_elementor_41904dc .uc-button-addcart.added{
    display:none;
  }

#uc_woocommerce_product_grid_elementor_41904dc.uc_post_grid_style_one .uc_post_grid_style_one_wrap {	
    display: grid;
}

    #uc_woocommerce_product_grid_elementor_41904dc.uc_post_grid_style_one .uc_content{
      flex-grow: 1;
      display: flex;
      flex-flow: column nowrap;
    }
    #uc_woocommerce_product_grid_elementor_41904dc .ue_grid_item_bottom    {
      margin-top:auto;
    }

  .uc_post_grid_style_one .uc_post_grid_style_one_item {
      flex-direction:column;
      display:flex;
  }





@media (max-width:1023px){
	#uc_woocommerce_product_grid_elementor_41904dc.uc_post_grid_style_one .uc_post_grid_style_one_wrap {
